-- =============================================================================
-- Datos de prueba Notion — seed_notion_demo_data.sql
-- Generado por: node scripts/generate-notion-seed-sql.mjs
--
-- Usa los usuarios EXISTENTES (primer registro de cada rol: dev, admin, user).
-- Incluye columnas de todos los tipos, filas con fechas antiguas, papelera,
-- 2 compartidos aceptados + 1 pendiente, áreas en usuarios y mensajes.
--
--   mysql -u USUARIO -p qmfqbfes_dashboard < sql/seed_notion_demo_data.sql
--
-- Tras ejecutar (opcional, si sirves JSON estático):
--   curl 'https://TU-DOMINIO/out/api/sync.php?secret=SYNC_SECRET_2026&mode=db_to_json'
-- =============================================================================

SET NAMES utf8mb4;
SET @now := NOW();

SET @uid_dev   := (SELECT id FROM users WHERE role = 'dev'   ORDER BY created_at LIMIT 1);
SET @uid_admin := (SELECT id FROM users WHERE role = 'admin' ORDER BY created_at LIMIT 1);
SET @uid_user  := (SELECT id FROM users WHERE role = 'user'  ORDER BY created_at LIMIT 1);

SELECT
  @uid_dev   AS dev_id,
  (SELECT display_name FROM users WHERE id = @uid_dev)   AS dev_name,
  @uid_admin AS admin_id,
  (SELECT display_name FROM users WHERE id = @uid_admin) AS admin_name,
  @uid_user  AS user_id,
  (SELECT display_name FROM users WHERE id = @uid_user)  AS user_name;

START TRANSACTION;

UPDATE users SET areas = '["Recursos Humanos","Logística","Contabilidad","Soporte","Marketing"]', updated_at = @now WHERE id = @uid_dev;
UPDATE users SET areas = '["Recursos Humanos","Contabilidad","Operaciones"]', updated_at = @now WHERE id = @uid_admin;
UPDATE users SET areas = '["Logística","Recursos Humanos"]', updated_at = @now WHERE id = @uid_user;

DELETE FROM messages WHERE id LIKE 'seed_msg_%';
DELETE FROM notion_shares WHERE id LIKE 'seed_share_%';
DELETE FROM notion_tasks WHERE tab_id LIKE 'seed_%';
DELETE FROM notion_columns WHERE tab_id LIKE 'seed_%';

DELETE FROM notion_tabs WHERE user_id = @uid_dev;
